ALTER TABLE "publication_requests" ADD CONSTRAINT "publication_requests_repository_canonical" CHECK ("publication_requests"."repository" ~ '^[a-z0-9_.-]+/[a-z0-9_.-]+$' and "publication_requests"."repository" !~ '[.]git$');--> statement-breakpoint
ALTER TABLE "publication_requests" ADD CONSTRAINT "publication_requests_repository_bindings" CHECK (("publication_requests"."bindings"->>'repository') is not distinct from "publication_requests"."repository" and ("publication_requests"."bindings"->>'operation' = 'push' or ("publication_requests"."bindings"->>'sourceRepository') is not distinct from "publication_requests"."repository"));